import { RcppaySttusCd } from '~/shared/api/dtos/enums';

type DisplayAmountProps = {
  amount: number;
  type: RcppaySttusCd;
};

export const DisplayAmount = ({ amount, type }: DisplayAmountProps) => {
  const isDeposit = type === RcppaySttusCd.입금코드;
  const signClass = isDeposit ? 'sign-plus' : 'sign-minus';
  const sign = isDeposit ? '+' : '-';

  return (
    <div className="common-transactions-value-wrapper">
      <span className={`common-transactions-sign ${signClass}`}>{sign}</span>
      <span className={`common-transactions-value ${signClass}`}>{amount.toLocaleString()}</span>
      <span className="common-transactions-won">원</span>
    </div>
  );
};
